import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.ktMMbWgA.js";const o="/intelligence-computed/lectures/L30-ai-coding/demo/figures/evaluator_richness.png",u=JSON.parse('{"title":"第 30 讲 · AI 编程协作 — 当 AI 成为你的搭档","description":"","frontmatter":{"title":"第 30 讲 · AI 编程协作 — 当 AI 成为你的搭档","act":5,"kind":"notes","prev":{"text":"L29 · 多模态应用","link":"/lectures/L29-multimodal/"},"next":{"text":"L31 · 评估、监控与 LLMOps","link":"/lectures/L31-llmops/"}},"headers":[],"relativePath":"lectures/L30-ai-coding/index.md","filePath":"lectures/L30-ai-coding/index.md","lastUpdated":null}'),i={name:"lectures/L30-ai-coding/index.md"};function l(r,t,d,p,c,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="第-30-讲-·-ai-编程协作-—-当-ai-成为你的搭档" tabindex="-1">第 30 讲 · AI 编程协作 — 当 AI 成为你的搭档 <a class="header-anchor" href="#第-30-讲-·-ai-编程协作-—-当-ai-成为你的搭档" aria-label="Permalink to &quot;第 30 讲 · AI 编程协作 — 当 AI 成为你的搭档&quot;">​</a></h1><blockquote><p>第 29 讲让 AI 能看、能画、能听——感知层补齐了。但最能检验 AI 综合能力的场景是<strong>编程</strong>：理解意图、规划方案、编辑代码、运行验证、反思修正——完整的 PGE 闭环。本讲揭示一个反直觉的事实：<strong>最好的 AI 编程不是&quot;AI 写完你审&quot;，而是&quot;你想 AI 做&quot;——协作模式决定产出质量。AI 参与度越高，对人类意图表达和判断力的要求反而越高。</strong></p></blockquote><table tabindex="0"><thead><tr><th>前置知识</th><th>核心产出</th><th>建议用时</th></tr></thead><tbody><tr><td>第 26 讲（Agent 与 PGE 框架）、第 27 讲（Skill 装配）、第 22 讲（上下文工程）</td><td>① 理解 AI 编程的三代进化（补全 → 对话 → Agentic Coding）② 理解 Agentic Coding = PGE 在编程场景的实例化 ③ 能横评六大 AI 编程工具的定位差异 ④ 掌握&quot;我想 AI 做&quot;的高效协作模式 ⑤ 理解 FIM 与 SWE-bench</td><td>阅读约 45 分钟 + 动手 15 分钟</td></tr></tbody></table><hr><h2 id="从上一讲到这一讲" tabindex="-1">从上一讲到这一讲 <a class="header-anchor" href="#从上一讲到这一讲" aria-label="Permalink to &quot;从上一讲到这一讲&quot;">​</a></h2><p>第 29 讲问：<strong>如果 AI 能写代码呢？谁才是真正的程序员？</strong></p><p>上一讲你看到 AI 能看懂 X 光片、能生成产品海报、能理解架构图——多模态感知补齐了。但这些能力你是用代码搭出来的：写 MCP Server、搭 Agent 循环、接 CLIP API……</p><p>现在问题来了：<strong>AI 编程助手正在学会做你正在做的事</strong>——理解需求 → 规划方案 → 写代码 → 运行验证 → 反思修正。这不就是第 26 讲的 PGE 闭环吗？</p><p>但一个关键洞察是：AI 参与度越高，对人类的要求反而越高——不是写代码的能力，而是<strong>表达意图和做出判断</strong>的能力。200 行代码里人类只写了 15 行，但那 15 行 edge case 修复值过其他所有代码。</p><hr><h2 id="_1-ai-编程的三代进化" tabindex="-1">1. AI 编程的三代进化 <a class="header-anchor" href="#_1-ai-编程的三代进化" aria-label="Permalink to &quot;1. AI 编程的三代进化&quot;">​</a></h2><h3 id="_1-1-第一代-代码补全-2021–2023" tabindex="-1">1.1 第一代：代码补全（2021–2023） <a class="header-anchor" href="#_1-1-第一代-代码补全-2021–2023" aria-label="Permalink to &quot;1.1 第一代：代码补全（2021–2023）&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>第一代 AI 编程的本质是 Fill-in-the-Middle（FIM）</strong>——模型看到你写的上下文（光标前后的代码），预测中间缺失的部分。底层是在代码上微调的语言模型（如 OpenAI Codex）。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你输入: def fibonacci(n):</span></span>
<span class="line"><span>            if n &lt;= 1:</span></span>
<span class="line"><span>                return n</span></span>
<span class="line"><span>            █                    ← 光标位置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AI 补全:     return fibonacci(n-1) + fibonacci(n-2)</span></span></code></pre></div><p>代码补全的特征：</p><ul><li><strong>速度极快</strong>——模型小（几 B 参数），响应时间 &lt; 200ms</li><li><strong>无需对话</strong>——Tab 接受，Esc 拒绝</li><li><strong>System 1 思维</strong>——快、直觉、不需要深思（呼应第 1 讲）</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">FIM 的技术细节</p><p>FIM 训练时把代码随机切成三段：prefix、middle、suffix。训练目标是给定 prefix + suffix 预测 middle。这比纯 next-token prediction 更适合代码补全场景——因为写代码时你经常在已有代码的&quot;中间&quot;插入内容。</p></div><h3 id="_1-2-第二代-对话编程-2023–2024" tabindex="-1">1.2 第二代：对话编程（2023–2024） <a class="header-anchor" href="#_1-2-第二代-对话编程-2023–2024" aria-label="Permalink to &quot;1.2 第二代：对话编程（2023–2024）&quot;">​</a></h3><p>ChatGPT 的出现让开发者开始用自然语言描述需求，AI 生成代码片段。IDE 集成的 Chat 面板（Copilot Chat、Cursor Chat）让对话编程成为主流。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户: &quot;帮我写一个 Python 函数，读取 CSV 文件，</span></span>
<span class="line"><span>      计算每列的平均值，返回字典&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AI: def calculate_column_averages(filepath: str) -&gt; dict:</span></span>
<span class="line"><span>        import csv</span></span>
<span class="line"><span>        ...</span></span></code></pre></div><p>进步：可以处理更复杂的需求，可以解释代码、修复 bug。 限制：<strong>一次一个片段</strong>——不能跨多个文件协调修改、不能运行验证、不能自我纠错。</p><h3 id="_1-3-第三代-agentic-coding-2024–现在" tabindex="-1">1.3 第三代：Agentic Coding（2024–现在） <a class="header-anchor" href="#_1-3-第三代-agentic-coding-2024–现在" aria-label="Permalink to &quot;1.3 第三代：Agentic Coding（2024–现在）&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>Agentic Coding = PGE 框架在编程场景的实例化。</strong> Agent 不只是生成代码片段——它能自主规划修改方案、在多个文件间协调编辑、运行测试验证、根据报错自我修正。这是一个完整的 Plan → Ground → Evaluate 循环。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agentic Coding 的 Agent Loop:</span></span>
<span class="line"><span>1. 上下文收集（Context Gathering）</span></span>
<span class="line"><span>   → 读取相关文件、搜索代码库、理解项目结构</span></span>
<span class="line"><span>2. 规划（Plan）</span></span>
<span class="line"><span>   → &quot;需要修改 3 个文件：model.py, router.py, test_model.py&quot;</span></span>
<span class="line"><span>3. 编辑（Ground）</span></span>
<span class="line"><span>   → 在每个文件中执行精确的代码修改</span></span>
<span class="line"><span>4. 验证（Evaluate）</span></span>
<span class="line"><span>   → 运行测试、检查编译、执行 lint</span></span>
<span class="line"><span>5. 反思（Reflect）</span></span>
<span class="line"><span>   → 测试失败？分析原因、调整方案、回到步骤 2</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">直觉</p><p>代码补全是&quot;AI 帮你打字&quot;（System 1），对话编程是&quot;AI 帮你写函数&quot;，Agentic Coding 是&quot;AI 帮你做项目&quot;（System 2）。从自动补全到自主编程——AI 编程的进化和人类思维模式的分层惊人地对应。</p></div><div class="note custom-block github-alert"><p class="custom-block-title">业界五级分类参考</p><p>业界另有按<strong>自主度</strong>划分的五级框架：Level 1 Autocomplete / Level 2 Chat / Level 3 Agentic / Level 4 Harness-Driven / Level 5 Dark Factory。本课程选择&quot;三代技术进化&quot;框架（补全→对话→Agentic），因为它与 System 1/2 和 PGE 叙事线更自然地对接。Level 4/5 的内容分别在下文 1.4 和第 31 讲中覆盖。</p></div><h3 id="_1-4-从个人到组织-harness-driven-模式" tabindex="-1">1.4 从个人到组织：Harness-Driven 模式 <a class="header-anchor" href="#_1-4-从个人到组织-harness-driven-模式" aria-label="Permalink to &quot;1.4 从个人到组织：Harness-Driven 模式&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>当 Agentic Coding 从个人工具升级为组织级编排系统，就进入了 Harness-Driven 模式。</strong> 核心架构：Planner Agent 拆解任务 → 多个 Generator Agent 并行写代码 → Evaluator Agent 跑测试和静态分析 → 门控审查点（Gated Checkpoint）由人类审核后才能合并。这是第 26 讲 PGE + 第 27 讲 Sub-agent 分解在编程场景的规模化落地。</p></div><p>工业案例：Stripe 的 Minions 系统据报道每周产出超过 1,300 个 AI 生成的 Pull Request。关键设计：</p><ul><li><strong>子任务隔离</strong>：大任务被拆解为小粒度子任务，每个子任务在新鲜的上下文窗口中独立完成，避免 context rot（长会话中模型理解退化）</li><li><strong>门控审查</strong>：自动测试 + 人工审查的双重门控，确保合并质量</li><li><strong>渐进放权（Progressive Autonomy）</strong>：从低风险任务（依赖更新、测试生成）开始，逐步扩展 Agent 的权限范围</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">常见误区</p><p><strong>从 Level 3 到 Level 4 的关键转变不是换工具，而是建基础设施。</strong> 需要：定义好的任务分解模板、可靠的 CI 管线、明确的审查门控规则、渐进式放权策略。大多数团队低估了这个基础设施投入——他们以为&quot;prompt 写好点&quot;就能规模化，但真正的瓶颈在编排层。</p></div><hr><h2 id="_2-六大工具横评" tabindex="-1">2. 六大工具横评 <a class="header-anchor" href="#_2-六大工具横评" aria-label="Permalink to &quot;2. 六大工具横评&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>类型</th><th>核心模式</th><th>上下文策略</th><th>适用场景</th><th>成本</th></tr></thead><tbody><tr><td><strong>GitHub Copilot</strong></td><td>IDE 插件</td><td>补全 + Chat + Agent</td><td>Workspace 索引</td><td>日常开发</td><td>$10-19/月</td></tr><tr><td><strong>Cursor</strong></td><td>独立 IDE</td><td>Chat + Composer + Agent</td><td>Codebase 索引 + Rules</td><td>中型项目重构</td><td>$20/月</td></tr><tr><td><strong>Claude Code</strong></td><td>CLI Agent</td><td>全 Agentic</td><td>文件系统 + CLAUDE.md</td><td>复杂跨文件任务</td><td>按 token 计费</td></tr><tr><td><strong>Windsurf</strong></td><td>独立 IDE</td><td>Cascade（多步 Agent）</td><td>全项目感知</td><td>全栈开发</td><td>$10-15/月</td></tr><tr><td><strong>Devin</strong></td><td>云端 Agent</td><td>全自主（沙箱环境）</td><td>完整开发环境</td><td>独立子任务</td><td>$500/月</td></tr><tr><td><strong>Codex</strong></td><td>云端 Agent</td><td>异步 Agentic</td><td>Git 仓库 + 环境</td><td>批量任务</td><td>按 token 计费</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">常见误区</p><p><strong>&quot;最贵的工具最好&quot;是错误的。</strong> Devin 月费 $500 但需要非常精确的任务描述和持续的结果审查。对大多数开发者来说，Copilot + Claude Code 的组合（补全 + 复杂任务）覆盖 90% 的需求，月成本 &lt; $50。<strong>工具选择取决于任务类型，而非价格。</strong></p></div><hr><h2 id="_3-协作模式-我想-ai-做-vs-ai-写我审" tabindex="-1">3. 协作模式：&quot;我想 AI 做&quot; vs &quot;AI 写我审&quot; <a class="header-anchor" href="#_3-协作模式-我想-ai-做-vs-ai-写我审" aria-label="Permalink to &quot;3. 协作模式：&quot;我想 AI 做&quot; vs &quot;AI 写我审&quot;&quot;">​</a></h2><h3 id="_3-1-两种反模式" tabindex="-1">3.1 两种反模式 <a class="header-anchor" href="#_3-1-两种反模式" aria-label="Permalink to &quot;3.1 两种反模式&quot;">​</a></h3><div class="warning custom-block github-alert"><p class="custom-block-title">反模式一：&quot;AI 写完我审&quot;</p><p>让 AI 生成大段代码，然后逐行审查。问题：审查 AI 生成的 200 行代码和自己写 200 行代码花的时间差不多——你失去了 AI 的效率优势，又没有获得自己写代码时的深度理解。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">反模式二：&quot;AI 全自动&quot;</p><p>把完整需求丢给 AI，不做任何引导和审查。问题：AI 不知道你的隐含约束（&quot;这个 API 不能用&quot;、&quot;这个 edge case 很重要&quot;），生成的代码可能在功能上正确但在工程上不可接受。</p></div><h3 id="_3-2-正确模式-我想-ai-做" tabindex="-1">3.2 正确模式：&quot;我想 AI 做&quot; <a class="header-anchor" href="#_3-2-正确模式-我想-ai-做" aria-label="Permalink to &quot;3.2 正确模式：&quot;我想 AI 做&quot;&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>高效的 AI 编程协作是&quot;人类负责意图和判断，AI 负责执行和验证&quot;。</strong> 人类做三件事：① 清晰表达意图（Context Engineering 呼应 L22）② 分解任务粒度 ③ 审查关键决策点。AI 做三件事：① 执行编辑 ② 运行验证 ③ 处理重复性工作。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高效协作流程:</span></span>
<span class="line"><span>人类: &quot;在 auth 模块中添加 OAuth2 支持，使用 PKCE 流程，</span></span>
<span class="line"><span>      要和现有的 JWT 验证兼容。先看 auth/ 目录理解现有架构。&quot;</span></span>
<span class="line"><span>                                          ↓ 清晰的意图 + 约束</span></span>
<span class="line"><span>AI:   [读取 auth/ 目录结构和关键文件]</span></span>
<span class="line"><span>      [制定方案: 修改 3 个文件，新增 1 个文件]</span></span>
<span class="line"><span>      [展示方案给人类]</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>人类: &quot;方案 OK，但 token 刷新的逻辑要用异步，</span></span>
<span class="line"><span>      不要阻塞主请求。&quot;</span></span>
<span class="line"><span>                                          ↓ 关键决策点的判断</span></span>
<span class="line"><span>AI:   [执行修改 + 写测试 + 运行测试 + 自我修正]</span></span>
<span class="line"><span>      [报告: 4 个文件已修改，12 个测试通过]</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">直觉</p><p>这就像一个好的 CEO 和执行团队的关系——CEO 不写代码，但她决定做什么、怎么做、什么不能做。AI 参与度越高，人类&quot;决策密度&quot;反而越高——每个决策都更重要。</p></div><h3 id="_3-3-上下文管理的关键实践" tabindex="-1">3.3 上下文管理的关键实践 <a class="header-anchor" href="#_3-3-上下文管理的关键实践" aria-label="Permalink to &quot;3.3 上下文管理的关键实践&quot;">​</a></h3><p>Agentic Coding 的效果严重依赖上下文质量（呼应第 22 讲上下文工程）：</p><table tabindex="0"><thead><tr><th>实践</th><th>工具支持</th><th>效果</th></tr></thead><tbody><tr><td><strong>CLAUDE.md / .cursorrules</strong></td><td>Claude Code / Cursor</td><td>项目级约束和偏好持久化</td></tr><tr><td><strong>Skill 定制</strong></td><td>Claude Code（Skill）</td><td>特定领域的代码规范</td></tr><tr><td><strong>Hooks</strong></td><td>Claude Code（Hooks）</td><td>自动化的前置/后置检查</td></tr></tbody></table><hr><h2 id="_4-fim-与-swe-bench" tabindex="-1">4. FIM 与 SWE-bench <a class="header-anchor" href="#_4-fim-与-swe-bench" aria-label="Permalink to &quot;4. FIM 与 SWE-bench&quot;">​</a></h2><h3 id="_4-1-fill-in-the-middle-详解" tabindex="-1">4.1 Fill-in-the-Middle 详解 <a class="header-anchor" href="#_4-1-fill-in-the-middle-详解" aria-label="Permalink to &quot;4.1 Fill-in-the-Middle 详解&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">技术细节</p><p>FIM 的训练格式：<code>&lt;PRE&gt;prefix&lt;SUF&gt;suffix&lt;MID&gt;middle</code>。模型学会根据前缀和后缀预测中间缺失的代码。这和标准的 next-token prediction（只看前文预测下一个 token）有本质区别——FIM 利用了<strong>双向上下文</strong>，更适合代码编辑场景。</p></div><h3 id="_4-2-swe-bench-agent-编程能力的标准评估" tabindex="-1">4.2 SWE-bench：Agent 编程能力的标准评估 <a class="header-anchor" href="#_4-2-swe-bench-agent-编程能力的标准评估" aria-label="Permalink to &quot;4.2 SWE-bench：Agent 编程能力的标准评估&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>SWE-bench（Software Engineering Benchmark）是评估 AI 编程 Agent 的标准基准。</strong> 它从真实 GitHub 仓库中收集 issue + 对应的 pull request，要求 Agent 自主定位问题、编写修复代码、通过测试。SWE-bench Verified 版本经人工审核，是目前最权威的 Agentic Coding 评估。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SWE-bench 任务流程:</span></span>
<span class="line"><span>1. 给 Agent 一个 GitHub issue 描述</span></span>
<span class="line"><span>2. Agent 拥有完整的代码仓库</span></span>
<span class="line"><span>3. Agent 需要:</span></span>
<span class="line"><span>   - 定位相关文件</span></span>
<span class="line"><span>   - 理解 bug 原因</span></span>
<span class="line"><span>   - 编写修复代码</span></span>
<span class="line"><span>   - 确保测试通过</span></span>
<span class="line"><span>4. 评估: diff 是否正确解决了 issue</span></span></code></pre></div><p>截至 2025 年中，最佳系统在 SWE-bench Verified 上的解决率约为 70%——意味着 AI 能自主修复约七成的真实 GitHub issue，但仍有三成问题超出当前能力。</p><p><img src="`+o+`" alt="Evaluator 信号丰富度：三代 AI 编程的评估维度对比"></p><hr><h2 id="动手环节" tabindex="-1">动手环节 <a class="header-anchor" href="#动手环节" aria-label="Permalink to &quot;动手环节&quot;">​</a></h2><blockquote><p>[!example] 动手 体验 AI 编程三代进化的差异：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lectures/L30-ai-coding/demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coding_eval_viz.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # Evaluator 信号丰富度可视化</span></span></code></pre></div><p>体验 Agentic Coding（需要 Claude Code）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 安装 Claude Code</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                      # 启动 Agent</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 尝试: &quot;阅读项目结构，添加一个 /health 端点，包含测试&quot;</span></span></code></pre></div><p>可视化代码见 <a href="/intelligence-computed/lectures/L30-ai-coding/demo/coding_eval_viz.py"><code>demo/coding_eval_viz.py</code></a>。</p></blockquote><hr><h2 id="_2026-现状速记-2026-04-快照" tabindex="-1">2026 现状速记（2026-04 快照） <a class="header-anchor" href="#_2026-现状速记-2026-04-快照" aria-label="Permalink to &quot;2026 现状速记（2026-04 快照）&quot;">​</a></h2><p>AI 编程是 2025–2026 年产品迭代最快的赛道，“Agentic” 已从实验仪变成默认交互范式：</p><table tabindex="0"><thead><tr><th>产品</th><th>定位</th><th>2026 快照</th></tr></thead><tbody><tr><td><strong>Claude Code</strong> (Anthropic CLI, 2025-02 GA)</td><td>终端-原生 Agentic，能跨仓库作业</td><td>Anthropic 官方旗舰，SWE-bench Verified 75％+</td></tr><tr><td><strong>Cursor</strong></td><td>IDE-主场在线交付，Composer / Background Agent</td><td>付费用户突破1M，产品创新颞</td></tr><tr><td><strong>Devin 2.x</strong> (Cognition)</td><td>全托管 Agentic dev，后端运行</td><td>GA 后价格调零售，在 Notion/Coda 类产品中集成</td></tr><tr><td><strong>GitHub Copilot Workspace + Spark</strong></td><td>GitHub 原生 Agentic</td><td>Workspace 2.x · 可生成微服务脚手架</td></tr><tr><td><strong>Aider / Continue.dev / Windsurf</strong></td><td>开源与高可控选择</td><td>Aider 仍是 CLI Agent 最轻量代表</td></tr><tr><td><strong>Amazon Q Developer / Google Jules</strong></td><td>云原生集成</td><td>AWS 与 GCP 听报 Agent，原生跨 PR 作业</td></tr></tbody></table><p>关键趋势：</p><ul><li><strong>SWE-bench Verified 从 2024 年末的 ~50％ 涨到 2026 年初的 75％+</strong>，社区预计年内将跨过 80％。</li><li><strong>Harness-Driven Autonomy 成为标配</strong>：企业部署默认启用门控审查、分阶段放权、可回滚点检。</li><li><strong>“Vibe Coding” vs “Spec-Driven” 二分法兴起</strong>：个人快原型 vs 企业交付代码，对 Agent 的期望与门控完全不同。</li><li><strong>代码生成与运行时验证闭环</strong>：e2b / Modal / Daytona 等提供安全沙箱让 Agent 可反复运行生成代码 + 读取 stack trace + 自修复。</li><li><strong>趋势反思</strong>：“Agent 帮你写代码” → “Agent 帮你作决策”——人类从“写代码者”变成“代码审查者 + 产品决策者”，技能重心从“快”转向“准”。</li></ul><hr><h2 id="失败模式-反例" tabindex="-1">失败模式 / 反例 <a class="header-anchor" href="#失败模式-反例" aria-label="Permalink to &quot;失败模式 / 反例&quot;">​</a></h2><blockquote><p>本节列出本讲核心结论<strong>不适用</strong>或<strong>易被误用</strong>的常见情境。教学的目的不是制造「已学会」的错觉，而是认清边界。</p></blockquote><ul><li>「AI 写代码 = 软件工程被颠覆」过早：Copilot/Cursor 在新项目 / 算法题上表现好；在<strong>大型遗留代码库</strong>上仍需大量人工干预——SWE-bench Verified 仅 ~50%。</li><li>Hallucinated API 的代价：GPT-4 生成的代码 ~5% 调用了不存在的 API；不跑测试就 commit 是新一类技术债。</li><li>「AI 提升 10× 生产力」证据薄弱：GitHub Copilot 用户调查显示主观提升 30-55%，<strong>客观</strong>测量（DORA metrics）多在 5-15%——存在显著主观偏差。</li><li>Devin / Claude Code 的边界：在有清晰 spec + 完整测试的项目上接近人类；spec 模糊或新需求探索时仍是「高级自动补全」。</li></ul><h2 id="本讲小结" tabindex="-1">本讲小结 <a class="header-anchor" href="#本讲小结" aria-label="Permalink to &quot;本讲小结&quot;">​</a></h2><ol><li><strong>AI 编程经历了三代进化</strong>——代码补全（FIM，System 1）→ 对话编程（Chat，单次生成）→ Agentic Coding（PGE 闭环，System 2），核心变化是 AI 从&quot;帮你打字&quot;到&quot;帮你做项目&quot;。</li><li><strong>Agentic Coding = PGE 在编程场景的实例化</strong>——上下文收集 → 规划 → 编辑 → 验证 → 反思，Agent 自主完成跨文件修改和测试验证。组织级规模化则需要 Harness-Driven 编排（门控审查 + 渐进放权）。</li><li><strong>高效协作是&quot;我想 AI 做&quot;而非&quot;AI 写我审&quot;</strong>——人类负责意图表达和关键判断，AI 负责执行和验证。AI 参与度越高，人类的决策密度反而越高。</li><li><strong>SWE-bench 是 Agentic Coding 的标准评估</strong>——基于真实 GitHub issue 的端到端评测，当前最佳约 70% 解决率，仍有显著提升空间。</li></ol><hr><h2 id="下一讲预告" tabindex="-1">下一讲预告 <a class="header-anchor" href="#下一讲预告" aria-label="Permalink to &quot;下一讲预告&quot;">​</a></h2><blockquote><p><strong>敌意问题</strong>：你现在学会了和 AI 一起写代码——Claude Code 帮你建应用、Copilot 帮你补全、Cursor 帮你重构。看起来 AI 什么都能做了。但你有没有想过：<strong>这个应用你敢直接上线吗？</strong> 用户量涨 10 倍扛得住吗？模型幻觉能检测到吗？出事能 5 分钟回滚吗？<strong>评估、监控、灰度、回滚——隔着整个工程体系。</strong></p></blockquote><p>第 31 讲——「评估、监控与 LLMOps」——从能用到可靠。</p><hr><h2 id="📺-推荐视频" tabindex="-1">📺 推荐视频 <a class="header-anchor" href="#📺-推荐视频" aria-label="Permalink to &quot;📺 推荐视频&quot;">​</a></h2><ol><li>🎬 <strong><a href="https://www.youtube.com/watch?v=9uw3F6rndnA" target="_blank" rel="noreferrer">Andrej Karpathy — Software 2.0</a></strong> — 经典演讲，预见了神经网络将取代传统编程的趋势，是理解 AI Coding 的思想基础。</li><li>🎬 <strong><a href="https://www.youtube.com/watch?v=jKrEk3C1xFM" target="_blank" rel="noreferrer">Fireship — AI Coding Tools Compared</a></strong> — 快速横评主流 AI 编程工具（Copilot / Cursor / Claude Code），直观展示三代进化的差异。</li><li>🎬 <strong><a href="https://www.youtube.com/watch?v=oFfVt3S51T4" target="_blank" rel="noreferrer">Lex Fridman Podcast — Cursor Team Interview</a></strong> — Cursor 团队深入讨论 Agentic Coding 的工程挑战和未来方向。</li></ol><hr><h2 id="🔗-互动资源" tabindex="-1">🔗 互动资源 <a class="header-anchor" href="#🔗-互动资源" aria-label="Permalink to &quot;🔗 互动资源&quot;">​</a></h2><ol><li>🔗 <strong><a href="https://github.com/features/copilot" target="_blank" rel="noreferrer">GitHub Copilot</a></strong> — 最广泛使用的 AI 编程助手，支持补全 + Chat + Agent 模式。</li><li>🔗 <strong><a href="https://www.cursor.com/" target="_blank" rel="noreferrer">Cursor</a></strong> — 以 AI 为核心的独立 IDE，内置 Codebase 索引和 Composer Agent。</li><li>🔗 <strong><a href="https://www.swebench.com/" target="_blank" rel="noreferrer">SWE-bench Leaderboard</a></strong> — Agentic Coding 的标准评测榜单，实时跟踪各 AI 编程系统的解决率。</li></ol><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ol><li>📝 <strong><a href="https://github.blog/news-insights/research/research-quantifying-github-copilots-impact-on-developer-productivity-and-happiness/" target="_blank" rel="noreferrer">GitHub Blog: Research on Copilot Productivity</a></strong> — GitHub 官方的 Copilot 生产力研究，量化补全对开发效率的影响<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>。</li><li>📄 <strong>Jimenez, C. et al. (2024). &quot;SWE-bench: Can Language Models Resolve Real-World GitHub Issues?&quot;</strong> — SWE-bench 基准论文<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>。</li><li>📝 <strong><a href="https://docs.anthropic.com/en/docs/agents-and-tools/claude-code/overview" target="_blank" rel="noreferrer">Anthropic: Claude Code Documentation</a></strong> — Claude Code 的官方文档，Agentic Coding 的设计理念与使用指南<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup>。</li><li>📝 <strong><a href="https://docs.cursor.com/" target="_blank" rel="noreferrer">Cursor Documentation</a></strong> — Cursor IDE 的架构和 Agent 模式文档。</li><li>📄 <strong>Chen, M. et al. (2021). &quot;Evaluating Large Language Models Trained on Code&quot;</strong> — Codex 原论文，FIM 和代码生成评估方法的基础<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup>。</li></ol><hr><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Kalliamvakou, E. et al. (2024). &quot;Research: Quantifying GitHub Copilot&#39;s Impact on Developer Productivity and Happiness&quot;. <em>GitHub Blog</em>. <a href="https://github.blog/news-insights/research/research-quantifying-github-copilots-impact-on-developer-productivity-and-happiness/" target="_blank" rel="noreferrer">github.blog</a> <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>Jimenez, C. et al. (2024). &quot;SWE-bench: Can Language Models Resolve Real-World GitHub Issues?&quot;. <em>ICLR</em>. <a href="https://arxiv.org/abs/2310.06770" target="_blank" rel="noreferrer">arxiv:2310.06770</a> <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p>Anthropic. (2025). &quot;Claude Code Documentation&quot;. <a href="https://docs.anthropic.com/en/docs/agents-and-tools/claude-code/overview" target="_blank" rel="noreferrer">docs.anthropic.com</a> <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p>Chen, M. et al. (2021). &quot;Evaluating Large Language Models Trained on Code&quot;. <a href="https://arxiv.org/abs/2107.03374" target="_blank" rel="noreferrer">arxiv:2107.03374</a> <a href="#fnref4" class="footnote-backref">↩︎</a></p></li></ol></section>`,88)])])}const b=a(i,[["render",l]]);export